insert into public.skill (slug, title, description)
values
  ($txt$g1-count$txt$, $txt$Reading, representing and counting numbers to 50$txt$, $txt$Say the number that comes just before or just after a number up to 20. Each number name matches one quantity.$txt$),
  ($txt$g1-compare$txt$, $txt$Comparing and ordering numbers to 50$txt$, $txt$Look at two numbers up to 20 and name the greater one. A number that comes later in the count is greater.$txt$),
  ($txt$g1-place$txt$, $txt$Composing and decomposing numbers to 50$txt$, $txt$A two-digit number is made of tens and ones. The tens digit tells how many groups of 10.$txt$),
  ($txt$g1-patterns$txt$, $txt$Patterns$txt$, $txt$A simple pattern grows by the same amount each time. Find the step, then apply it once more.$txt$),
  ($txt$g1-add-10$txt$, $txt$Addition facts to 10 and adding to 50$txt$, $txt$Add two numbers whose sum is 10 or less. Put the numbers together and count the total.$txt$),
  ($txt$g1-sub-10$txt$, $txt$Related subtraction facts and subtracting within 50$txt$, $txt$Subtract from a number up to 10. Count back, or think of the missing part.$txt$),
  ($txt$g1-share$txt$, $txt$Equal sharing and equal groups$txt$, $txt$Share a set into equal groups. Each group gets the same number, with none left over.$txt$),
  ($txt$g1-measure$txt$, $txt$Comparing length, area, mass and capacity$txt$, $txt$Length can be measured with same-sized units such as paperclips. Compare lengths by comparing the unit counts.$txt$),
  ($txt$g2-place$txt$, $txt$Reading, representing and decomposing numbers to 200$txt$, $txt$Numbers up to 100 are built from tens and ones. The place of a digit changes its value.$txt$),
  ($txt$g2-compare$txt$, $txt$Comparing and ordering numbers to 200$txt$, $txt$Order numbers to 100 by comparing tens first, then ones. The greatest number has the largest value.$txt$),
  ($txt$g2-fractions$txt$, $txt$Fair shares and equivalent fractions (thirds, sixths)$txt$, $txt$A fraction names equal parts of one whole. The bottom number tells how many equal parts, and the top tells how many are chosen.$txt$),
  ($txt$g2-even-odd$txt$, $txt$Even and odd numbers$txt$, $txt$Even numbers can be split into two equal groups. Odd numbers have one left over.$txt$),
  ($txt$g2-add-sub$txt$, $txt$Addition and subtraction within 100$txt$, $txt$Add and subtract numbers up to 100. Line up the ones and tens, and regroup when a column goes over 9 or below 0.$txt$),
  ($txt$g2-groups$txt$, $txt$Equal groups and equal sharing$txt$, $txt$Equal groups have the same number in each group. Multiply the number of groups by the size of one group.$txt$),
  ($txt$g2-measure$txt$, $txt$Measuring length in cm and m$txt$, $txt$Centimetres measure length. When part of a length is removed, subtract to find what is left.$txt$),
  ($txt$g2-data$txt$, $txt$Sorting, collecting and graphing data$txt$, $txt$A tally or pictograph counts how many. Add the counts, or compare them, to answer a question about the data.$txt$),
  ($txt$g3-place$txt$, $txt$Place value to 1,000$txt$, $txt$In a number up to 1,000, each digit has a hundreds, tens, or ones value. Multiply the digit by its place.$txt$),
  ($txt$g3-fractions$txt$, $txt$Fair shares and equivalent fractions$txt$, $txt$The denominator counts the equal parts in the whole. The numerator counts how many of those parts are being used.$txt$),
  ($txt$g3-add-sub$txt$, $txt$Addition and subtraction within 1,000$txt$, $txt$Add and subtract up to 1,000 by working one place at a time. Regroup tens, hundreds, and ones when you need to.$txt$),
  ($txt$g3-mult$txt$, $txt$Multiplication facts of 2, 5 and 10 (and related division facts)$txt$, $txt$Multiplication facts join equal groups. Knowing the facts to 10 × 10 makes larger calculations faster.$txt$),
  ($txt$g3-represent-arrays$txt$, $txt$Representing multiplication to 10 × 10 and division to 100 ÷ 10 with arrays$txt$, null),
  ($txt$g4-facts-10x10$txt$, $txt$Multiplication facts to 10×10$txt$, null),
  ($txt$g3-div-rem$txt$, $txt$Division with remainders$txt$, $txt$Sometimes a division does not come out even. The quotient is how many full groups fit, and the remainder is what is left.$txt$),
  ($txt$multiplication-and-division-problems-including-groups-of-1-2-1-4-1-3$txt$, $txt$Multiplication and division problems (including groups of 1/2, 1/4, 1/3)$txt$, null),
  ($txt$g3-perimeter$txt$, $txt$Perimeter of polygons$txt$, $txt$Perimeter is the distance around a rectangle. Add the length and width, then double that sum.$txt$),
  ($txt$g3-time$txt$, $txt$Telling time in hours, minutes and seconds$txt$, $txt$Read hours and minutes, then move forward by counting minutes. 60 minutes makes another hour.$txt$),
  ($txt$g3-data$txt$, $txt$Pictographs and bar graphs with scales$txt$, $txt$A bar graph uses the height of a bar as a count. Read the counts, then add or compare them.$txt$),
  ($txt$g4-equiv$txt$, $txt$Representing and comparing fractions (halves to tenths)$txt$, $txt$Equivalent fractions name the same amount. Multiply the numerator and the denominator by the same number.$txt$),
  ($txt$g4-place$txt$, $txt$Place value to 10,000$txt$, $txt$Each place to the left is worth ten times as much. Find the digit, then multiply by its place value.$txt$),
  ($txt$g4-round$txt$, $txt$Rounding numbers$txt$, $txt$To round, look at the digit to the right of the place you are rounding to. 5 or more rounds up. Less than 5 stays the same.$txt$),
  ($txt$g4-decimals$txt$, $txt$Decimal tenths$txt$, $txt$A decimal uses a point to show parts smaller than one. One tenth is 0.1, and tenths sit in the first decimal place.$txt$),
  ($txt$g4-mult$txt$, $txt$Multiplying 2- or 3-digit numbers by 1-digit numbers$txt$, $txt$Multiply a two-digit number by breaking it into tens and ones. Multiply each part, then add the partial products.$txt$),
  ($txt$g4-div$txt$, $txt$Dividing 2- or 3-digit numbers by 1-digit numbers (remainders as fractions)$txt$, $txt$Long division splits a number into equal groups of a one-digit divisor. Ask how many times the divisor fits, then multiply and subtract.$txt$),
  ($txt$repeated-addition-of-unit-fractions$txt$, $txt$Repeated addition of unit fractions$txt$, null),
  ($txt$g4-area$txt$, $txt$Area of rectangles$txt$, $txt$Area counts the square units inside a rectangle. Multiply the length by the width.$txt$),
  ($txt$g5-place$txt$, $txt$Place value to 100,000$txt$, $txt$A digit's place tells which power of ten it counts. Move one place left and the value becomes ten times as large.$txt$),
  ($txt$g5-decimals$txt$, $txt$Decimals to hundredths$txt$, $txt$Line up the decimal points before you add or subtract hundredths. The point in the answer stays in the same place.$txt$),
  ($txt$g5-mult$txt$, $txt$Multiplication facts to 12×12$txt$, $txt$Multiplication facts through 12 × 12 are the building blocks for larger products. Recall the fact, or build it from a nearby fact.$txt$),
  ($txt$g5-div-rem$txt$, $txt$Dividing 3-digit by 2-digit numbers (with remainders)$txt$, $txt$Divide into equal groups, then record what is left. The remainder is always smaller than the divisor.$txt$),
  ($txt$g5-frac$txt$, $txt$Adding and subtracting fractions with like denominators$txt$, $txt$Keep the shared denominator. Add or subtract only the numerators.$txt$),
  ($txt$g5-equations$txt$, $txt$Solving equations (whole numbers to 100)$txt$, $txt$An equation stays balanced when you do the same thing to both sides. Undo addition with subtraction.$txt$),
  ($txt$g5-area$txt$, $txt$Area of triangles and parallelograms$txt$, $txt$A parallelogram's area is base times height. A triangle is half of that parallelogram, so use 1/2 × base × height.$txt$),
  ($txt$g6-decimals$txt$, $txt$Decimals to thousandths$txt$, $txt$Thousandths are the third digit after the decimal point. Line the points up, including the thousandths place, before you add.$txt$),
  ($txt$g6-ratios$txt$, $txt$Ratios, rates and percents$txt$, $txt$A ratio compares two amounts. A unit rate tells the amount for one item. Scale both parts of a ratio by the same factor.$txt$),
  ($txt$g6-percent$txt$, $txt$Percent of a number (mental math)$txt$, $txt$Percent means out of 100. Convert the percent to a fraction of 100, then multiply by the number.$txt$),
  ($txt$g6-frac$txt$, $txt$Multiplying and dividing whole numbers by proper fractions$txt$, $txt$To multiply fractions, multiply the numerators and the denominators. To divide, multiply by the reciprocal of the second fraction.$txt$),
  ($txt$g6-equations$txt$, $txt$Solving equations with multiple terms (whole numbers)$txt$, $txt$Undo a decimal addition by subtracting the same decimal from both sides. The two sides stay equal.$txt$),
  ($txt$g6-area$txt$, $txt$Area of trapezoids, rhombuses, kites and composite polygons$txt$, $txt$Use the height that is perpendicular to the base. Triangle area is half of base times height. Parallelogram area is base times height.$txt$),
  ($txt$g6-surface$txt$, $txt$Surface area of prisms and pyramids$txt$, $txt$A prism has three pairs of faces. Find the area of each pair, then add the three results.$txt$),
  ($txt$g6-data$txt$, $txt$Range, mean, median and mode$txt$, $txt$The mean is the average. The median is the middle value once the numbers are ordered. The mode is the value that appears most often.$txt$),
  ($txt$g7-integers$txt$, $txt$Adding and subtracting integers$txt$, $txt$Integers include numbers below zero. Adding a negative moves left, and a negative times a negative is positive.$txt$),
  ($txt$g7-equations$txt$, $txt$Solving equations with multiple terms and decimals$txt$, $txt$Undo the added term first, then undo the multiplication. Do the same operation to both sides.$txt$),
  ($txt$g7-proportion$txt$, $txt$Proportional relationships$txt$, $txt$In a proportion, both amounts scale by the same factor. Find the cost or amount for one, then multiply.$txt$),
  ($txt$g7-percent$txt$, $txt$Fractions, decimals and percents$txt$, $txt$A percent of a price can be a discount or a part of a whole. Find the percent amount, then subtract it when the question asks for a sale price.$txt$),
  ($txt$g7-order$txt$, $txt$Order of operations$txt$, $txt$Multiply or divide before you add or subtract. Work from left to right when the operations have the same rank.$txt$),
  ($txt$g7-circles$txt$, $txt$Circumference and area of circles$txt$, $txt$Circumference is the distance around a circle: 2 × π × radius. Area is π × radius × radius. Use π = 3.14.$txt$),
  ($txt$g7-volume$txt$, $txt$Volume of prisms and cylinders$txt$, $txt$Prism volume is length × width × height. Cylinder volume is π × radius × radius × height. Use π = 3.14.$txt$),
  ($txt$g7-probability$txt$, $txt$Independent and dependent events$txt$, $txt$Probability is the number of favourable outcomes over the total number of equally likely outcomes.$txt$),
  ($txt$g8-interest$txt$, $txt$Simple and compound interest$txt$, $txt$Simple interest is principal × rate × time. Write the rate as a decimal before you multiply.$txt$),
  ($txt$g8-equations$txt$, $txt$Solving equations with integers and decimals$txt$, $txt$Simplify the parentheses, then undo addition and multiplication. Each step keeps both sides equal.$txt$),
  ($txt$g8-linear$txt$, $txt$Linear growing and shrinking patterns$txt$, $txt$A linear relation has the form y = mx + b. Substitute the x-value, multiply by the rate, then add the start value.$txt$),
  ($txt$g8-integers$txt$, $txt$Multiplying and dividing integers$txt$, $txt$Same signs give a positive result. Different signs give a negative result. Divide using the related multiplication fact.$txt$),
  ($txt$g8-pythagoras$txt$, $txt$Pythagorean theorem$txt$, $txt$In a right triangle, the square of the hypotenuse equals the sum of the squares of the two legs.$txt$),
  ($txt$g8-volume$txt$, $txt$Perimeter, area, volume and surface area of composite shapes$txt$, $txt$Use the prism formula length × width × height, or the cylinder formula π × radius² × height with π = 3.14.$txt$),
  ($txt$g7-cylinder-surface$txt$, $txt$Surface area of cylinders$txt$, null),
  ($txt$g8-data$txt$, $txt$Two-variable data and scatter plots$txt$, $txt$The range is the difference between the greatest and least values. The mean is the sum divided by how many numbers there are.$txt$)
